-- PT102-S2-Q11. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT102-S2-Q11$batch09$ AND q.stimulus=$batch09$A Habitat Conservation Plan (HCP) is based on a law that allows developers to use land inhabited by endangered species in exchange for a promise to preserve critical habitat or provide replacement land nearby. Some individuals of endangered species are lost in return for assurances by the owner or developer that habitat for those remaining animals will be protected. Environmentalists are pleased that HCPs allow them to win concessions from developers who would otherwise ignore rarely enforced environmental laws. Satisfied property owners prefer HCPs to more restrictive prohibitions of land use.$batch09$ AND q.prompt=$batch09$The situation described above most closely conforms to which one of the following principles?$batch09$ AND q.correct_choice=$batch09$D$batch09$) THEN RAISE EXCEPTION 'Question changed: PT102-S2-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT102-S2-Q11$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT102-S2-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT102-S2-Q11$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Situation$batch09$, $batch09$Under an HCP, developers get to use land where endangered species live. In return, they protect critical habitat or provide replacement land. Environmentalists like it because they win concessions from developers who would otherwise ignore weak laws. Property owners like it because it beats stricter bans.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$The last two sentences are the payoff: both sides are satisfied. Each gives something up and each gets something it wants. A law that leaves opposing parties both pleased is a law built to balance their interests.$batch09$), (2, $batch09$Goal$batch09$, $batch09$A principle about laws that reconcile the interests of developers and environmentalists.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT102-S2-Q11$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$Nobody mentions legal battles. The compromise here comes from the design of a law, not from environmentalists trying to stay out of court.$batch09$), ($batch09$B$batch09$, $batch09$Developers here give up land and make promises. Nothing says they get to skip laws they find burdensome.$batch09$), ($batch09$C$batch09$, $batch09$The HCP serves the interests of both parties, and both are satisfied. This principle says laws shouldn't try to do that.$batch09$), ($batch09$D$batch09$, $batch09$Developers get to build, environmentalists get habitat protection, and both are pleased. That is a law fashioned to reconcile their interests.$batch09$), ($batch09$E$batch09$, $batch09$"The most effective means" ranks every option for saving species. The passage describes one arrangement that pleases everyone. It never compares it to anything else or says species fare best this way.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT102-S2-Q11$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
